// Generated from backend/contracts/product-command.v1.schema.json and research-result.v2.schema.json.
export type ProductFact = { "key": string; "label": string; "value": string | number | boolean | null; "unit": string | null; "sourceUrls": Array<string>; "quote": string; "observedAt": string; "provenance": "researched" | "user-stated" | "corrected" | "accepted" | "superseded"; "verification": "reported" | "unverified" | "conflicting" | "user-confirmed" };
export type ProductOffer = { "url": string; "seller": string | null; "amount": number | null; "currency": string | null; "region": string | null; "availability": "in-stock" | "out-of-stock" | "preorder" | "unknown"; "sourceUrls": Array<string>; "observedAt": string };
export type ProductIdentity = { "brand": string | null; "model": string | null; "variant": string | null; "match": "exact" | "family" | "uncertain" };
export type ProductImage = { "url": string; "sourceUrl": string };
export type ProductEvidence = { "identity": ProductIdentity; "targetCandidateId": string | null; "image": ProductImage | null; "offers": Array<ProductOffer>; "facts": Array<ProductFact> };
export type Requirement = { "id": string; "label": string; "key": string; "operator": "lte" | "gte" | "eq" | "contains"; "value": string | number | boolean; "unit": string | null; "required": boolean; "provenance": "user-stated" };
export type RequirementSuggestion = { "label": string; "key": string; "operator": "lte" | "gte" | "eq" | "contains"; "value": string | number | boolean; "unit": string | null; "required": boolean; "contextQuote": string };
export type FactCorrection = { "key": string; "label": string; "value": string | number | boolean | null; "unit": string | null };
export type ProductCommand = { "actionId": string; "expectedRevision": number; "type": "requirements"; "payload": { "requirements": Array<Requirement> } } | { "actionId": string; "expectedRevision": number; "type": "correct-fact"; "payload": { "candidateId": string; "fact": FactCorrection } } | { "actionId": string; "expectedRevision": number; "type": "evidence-map"; "payload": { "axes": Array<string>; "judgment": string } };
export type ProductResearchResult = { "summary": string; "findings": Array<{ "label": string; "url": string; "summary": string; "price": { "amount": number; "currency": string } | null; "availability": string; "unknowns": Array<string>; "sources": Array<{ "url": string; "title": string }>; "details": ProductEvidence }>; "unknowns": Array<string>; "requirements": Array<RequirementSuggestion> };
